definitions.definition:
model VerificationToken {
  identifier String
  token String @unique
  expires DateTime
  @@unique([identifier, token])
}

enum BuildVisibility {
  PUBLIC
  PRIVATE
  UNLISTED
}

enum GroupRole {
 OWNER
 ADMIN
 OFFICER
 MEMBER
}

enum ContentVisibility {
 PUBLIC
 PRIVATE
 GROUP
}
